from collections import deque
def f(I):
    H,W=len(I),len(I[0])
    bg=max(set(x for r in I for x in r),key=lambda v:sum(r.count(v) for r in I))
    # flood bg from border
    seen=set(); q=deque()
    for r in range(H):
        for c in (0,W-1):
            if I[r][c]==bg: q.append((r,c)); seen.add((r,c))
    for c in range(W):
        for r in (0,H-1):
            if I[r][c]==bg: q.append((r,c)); seen.add((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            n=(r+dr,c+dc)
            if 0<=n[0]<H and 0<=n[1]<W and I[n[0]][n[1]]==bg and n not in seen:
                seen.add(n); q.append(n)
    O=[row[:] for row in I]
    for r in range(H):
        for c in range(W):
            if I[r][c]==bg and (r,c) not in seen:
                # nearest non-bg orthogonally
                best=None
                for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    x,y=r+dr,c+dc
                    while 0<=x<H and 0<=y<W and I[x][y]==bg:
                        x+=dr; y+=dc
                    if 0<=x<H and 0<=y<W and I[x][y]!=bg:
                        best=I[x][y]
                        break
                if best is not None: O[r][c]=best
    return O
